R=/scratch/jjyeung/orch_n30
mkdir -p $R/sb_rlrev4/prompts $R/sb_rlrev4/out; echo  | base64 -d > $R/sb_rlrev4/prompts/sb_rlrev4.md; echo sb_rlrev4 >> $R/sb_queue/queue.txt; echo Q: $(cat $R/sb_queue/queue.txt | tr "\n" " ")
w=sb_f64fix3; mkdir -p $R/$w; cp $R/sb_cursor_probe/AGENTS.md $R/$w/AGENTS.md; echo  | base64 -d > $R/$w/PROMPT.md
cd $R/$w && tmux new-session -d -s $w "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 3600 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 2; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo
